public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Create a boolean 2D array to represent the n-teresting space
    boolean[][] maze = new boolean[n][n];

    // Initialize the starting and ending n-tersections as discovered
    maze[start[0]][start[1]] = true;
    maze[end[0]][end[1]] = true;

    // Loop through each path between adjacent n-tersections
    for (int[] path : paths) {
        // If the path connects two n-tersections that are not yet discovered, mark them as discovered
        if (!maze[path[0]][path[1]] && !maze[path[2]][path[3]]) {
            maze[path[0]][path[1]] = true;
            maze[path[2]][path[3]] = true;
        }
    }

    // If the starting n-tersection is not discovered, return "cannot be travelled"
    if (!maze[start[0]][start[1]]) {
        return "cannot be travelled";
    }

    // If the starting n-tersection is still discovered and the ending n-tersection is not discovered, return "cannot be travelled"
    if (maze[start[0]][start[1]] && !maze[end[0]][end[1]]) {
        return "cannot be travelled";
    }

    // Otherwise, return "can be travelled"
    return "can be travelled";
}

