public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length == 0) {
        return false;
    }
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    if (sum % 2 != 0) {
        return false;
    }
    int target = sum / 2;
    return canPartition(nums, target, 0);
}

private boolean canPartition(int[] nums, int target, int start) {
    if (target == 0) {
        return true;
    }
    if (start == nums.length || target < 0) {
        return false;
    }
    for (int i = start; i < nums.length; i++) {
        if (nums[i] <= target) {
            if (canPartition(nums, target - nums[i], i + 1)) {
                return true;
            }
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int[] memo = new int[cost.length];
    Arrays.fill(memo, -1);
    return minCostClimbingStairsHelper(cost, 0, memo);
}

private int minCostClimbingStairsHelper(int[] cost, int index, int[] memo) {
    if (index >= cost.length) {
        return 0;
    }
    if (memo[index] != -1) {
        return memo[index];
    }
    int minCost = Integer.MAX_VALUE;
    for (int i = 0; i < 2; i++) {
        int currentCost = minCostClimbingStairsHelper(cost, index + 1, memo);
        minCost = Math.min(minCost, currentCost + cost[index]);
    }
    memo[index] = minCost;
    return minCost;
}

