public int maxUniqueSplit(String s) {
    int n = s.length();
    int[][] dp = new int[n][n];
    for (int i = 0; i < n; i++) {
        dp[i][i] = 1;
    }
    for (int len = 2; len <= n; len++) {
        for (int i = 0; i < n - len + 1; i++) {
            int j = i + len - 1;
            if (s.charAt(i) == s.charAt(j)) {
                dp[i][j] = 2 + dp[i + 1][j - 1];
            } else {
                dp[i][j] = Math.max(dp[i][j - 1], dp[i + 1][j]);
            }
        }
    }
    return dp[0][n - 1];
}

public int minOperations(String[] logs) {
    int numberOfSteps = 0;
    int currentDepth = 0;
    for (String currentLog : logs) {
        if (currentLog.equals("../")) {
            int numberOfStepsToRoot = currentDepth / 2;
            if (currentDepth % 2 == 1) {
                numberOfStepsToRoot++;
            }
            numberOfSteps += numberOfStepsToRoot;
            currentDepth -= numberOfStepsToRoot * 2;
        } else if (currentLog.endsWith("/")) {
            currentDepth++;
        } else if (currentLog.equals("./")) {
            continue;
        } else {
            throw new IllegalArgumentException("Invalid log: " + currentLog);
        }
    }
    return numberOfSteps;
}

