private static boolean isSteppingNumber(int num) {
    int prevDigit = -1;
    while (num > 0) {
        int digit = num % 10;
        if (prevDigit != -1 && Math.abs(digit - prevDigit) != 1) {
            return false;
        }
        prevDigit = digit;
        num /= 10;
    }
    return true;
}

