public static int squarePermutations(int[] A) {
    int n = A.length;
    int[][] dp = new int[n][n];
    for (int i = 0; i < n; i++) {
        dp[i][i] = 1;
    }
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            int diff = A[i] - A[j];
            if (Math.sqrt(diff * 1.0) % 1 == 0) {
                dp[i][j] = dp[i + 1][j - 1];
            }
        }
    }
    int result = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            result += dp[i][j];
        }
    }
    return result;
}

public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int[] left = new int[n];
    int[] right = new int[n];
    int[] maxArea = new int[n];

    left[0] = -1;
    right[n-1] = n;
    for (int i = 1; i < n; i++) {
        int idx = i - 1;
        while (idx >= 0 && heights[idx] >= heights[i]) {
            idx = left[idx];
        }
        left[i] = idx;
    }

    for (int i = n - 2; i >= 0; i--) {
        int idx = i + 1;
        while (idx < n && heights[idx] >= heights[i]) {
            idx = right[idx];
        }
        right[i] = idx;
    }

    for (int i = 0; i < n; i++) {
        maxArea[i] = Math.min(heights[i], heights[left[i]] * (i - left[i]));
        maxArea[i] = Math.min(maxArea[i], heights[right[i]] * (right[i] - i));
    }

    int maxAreaIdx = 0;
    for (int i = 1; i < n; i++) {
        if (maxArea[i] > maxArea[maxAreaIdx]) {
            maxAreaIdx = i;
        }
    }

    return maxArea[maxAreaIdx];
}

public static int[] diagonalOrder(int[][] mat) {
    int n = mat.length, m = mat[0].length;
    int[] result = new int[n * m];
    int i = 0;
    for (int diag = 0; diag < Math.max(n, m); diag++) {
        if (diag < m - n + 1) {
            for (int i = 0, j = diag; i < n && j < m; i++, j++) {
                result[i] = mat[i][j];
            }
        } else if (diag < m && diag > n - 1) {
            for (int i = diag - m + n, j = m - 1; i < n && j >= 0; i++, j--) {
                result[i] = mat[i][j];
            }
        } else if (diag >= m - 1) {
            for (int i = m - diag - 1, j = 0; i < n && j < m - diag; i++, j++) {
                result[i] = mat[i][j];
            }
        } else {
            for (int i = diag + 1, j = m - 1; i < n && j >= 0; i++, j--) {
                result[i] = mat[i][j];
            }
        }
    }
    return result;
}

