public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    for (int i = 1; i <= 9; i++) {
        String num = String.valueOf(i);
        if (n == 1) {
            result.add(num);
        } else {
            int len = num.length();
            int pad = (n - len) / 2;
            String paddedNum = String.valueOf(new char[pad]).replace("\0", "0") + num + String.valueOf(new char[pad]).replace("\0", "0");
            result.add(paddedNum);
        }
    }
    return result;
}

public static boolean isBoomerang(int[][] points) {
    return points.length == 3 && points[0][0] == points[1][1] && points[0][1] == points[1][0] && points[1][0] == points[2][1] && points[1][1] == points[2][0];
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer.");
    }
    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    for (int i = 1; i < n; i++) {
        int min = Math.min(Math.min(uglyNumbers[i2] * 2, uglyNumbers[i3] * 3), uglyNumbers[i5] * 5);
        uglyNumbers[i] = min;
        if (min == uglyNumbers[i2] * 2) {
            i2++;
        }
        if (min == uglyNumbers[i3] * 3) {
            i3++;
        }
        if (min == uglyNumbers[i5] * 5) {
            i5++;
        }
    }
    return uglyNumbers[n - 1];
}

public static int calculateEnergy(String s) {
    int energy = 0;
    char currentChar = s.charAt(0);
    int currentLength = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == currentChar) {
            currentLength++;
        } else {
            currentChar = s.charAt(i);
            currentLength = 1;
        }
        energy = Math.max(energy, currentLength);
    }
    return energy;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();

    for (int i = 1; i <= n; i++) {
        result.add(i);
    }

    Collections.sort(result);

    return result;
}

public static int calculateUniqueSum(int[] nums) {
    Set<Integer> uniqueNums = new HashSet<>();
    for (int num : nums) {
        uniqueNums.add(num);
    }
    int sum = 0;
    for (int num : uniqueNums) {
        sum += num;
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    int minSquares = 0;
    int currentSquare = 1;
    while (currentSquare <= n) {
        if (currentSquare == n) {
            minSquares++;
            break;
        } else if (currentSquare < n) {
            minSquares++;
            currentSquare += 4 * currentSquare + 1;
        }
    }
    return minSquares;
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    String reversedWords = "";
    for (String word : words) {
        char[] wordChars = word.toCharArray();
        String reversedWord = "";
        for (int i = wordChars.length - 1; i >= 0; i--) {
            reversedWord += wordChars[i];
        }
        reversedWords += reversedWord + " ";
    }
    return reversedWords;
}
